class Solution {
public:
    bool isDecomposable(string s) {
        int twos = 0;
        for (int i = 0; i < (int)s.size();) {
            int j = i;
            while (j < (int)s.size() && s[j] == s[i]) {
                ++j;
            }
            int rem = (j - i) % 3;
            if (rem == 1) {
                return false;
            }
            if (rem == 2) {
                ++twos;
            }
            i = j;
        }
        return twos == 1;
    }
};
